using System.Collections.Generic;

namespace TAOM.Features.TroopProgression;

// Volunteer recruitment pool for Dorwinion, the Northman vintners and river traders of the Sea of Rhûn (troops generated by
// tools/generate_dorwinion_troops.py). The data half of VolunteerRecruitmentService, registered by
// the static ctor in the core file. Lookup priority: conditional > settlement > clan > culture
// (troops.md).
public partial class VolunteerRecruitmentService
{
    private static void InitializeDorwinionCulture()
    {
        // Two roots reach the whole tree: the Levy heads the spear and bow lines, and the Noble heads the river riders and the Guard of Vineholm. Levy-heavy, as Cardolan's.
        CultureMap["dorwinion"] = new List<VolunteerChance>
        {
            new VolunteerChance("dorwinion_levy", 6),
            new VolunteerChance("dorwinion_noble", 2)
        };
    }
}
